    # horizontal same-color boundary bars define two independent filled columns/regions.
    bars=[]
    for r,row in enumerate(grid):
        vals=[(c,v) for c,v in enumerate(row) if v!=bg]
        if len(vals)>=2 and len(set(v for c,v in vals))==1 and [c for c,v in vals]==list(range(vals[0][0],vals[-1][0]+1)):
